 async function openHistory(){const d=dialog('سجل مراجعة واعتماد الأخبار'),box=E('div'),more=B('سجل أقدم',()=>busy(more,load),'secondary');d.append(box,more);let offset=0;async function load(){const rows=await call('history',{offset});offset+=rows.length;for(const r of rows){const row=E('article',undefined,'news-request-row');row.append(E('h3',r.title),E('p',({submitted:'إرسال الطلب',claimed:'حجز المراجعة',manager_takeover:'تولي المراجعة بواسطة المدير',draft_saved:'حفظ مسودة',released:'ترك المراجعة',approved:'اعتماد الخبر',published:'نشر الخبر',published_legacy:'نشر سابق',sent_for_approval:'إرسال لموافقة المدير',rejected:'رفض الطلب',cancelled:'إلغاء الطلب'}[r.event]||r.event)+' · '+r.actor_name),E('time',new Date(r.created_at).toLocaleString('ar-SA')));box.append(row)}more.hidden=rows.length<50;if(!offset)box.append(E('p','لا توجد إجراءات بعد.'))}await load()}
 async function refresh(){const n=++epoch;const active=state.user&&state.profile?.status==='active';plus.hidden=submit.hidden=mine.hidden=review.hidden=templates.hidden=historyButton.hidden=!active;managerTypes.hidden=addType.hidden=!active;if(!active)return;meta=await call('meta');if(n!==epoch)return;historyButton.hidden=review.hidden=!meta.writer;managerTypes.hidden=addType.hidden=templates.hidden=!meta.admin;review.textContent='مراجعة طلبات نشر الأخبار'+(meta.pending?' · '+meta.pending:'')}
